  ($str$Vertical Injection Molder | 800kN | 3K | 127g | 4 Station | 1200mm$str$, 800, 127, 3.7, 300, 600, 0, 0, 3, 4, false, $str$Vertical$str$, 1.6, 128000, 1200),
  ($str$Vertical Injection Molder | 800kN | 3K | 18g | 4 Station | 1200mm$str$, 800, 18, 3.7, 300, 600, 0, 0, 3, 4, false, $str$Vertical$str$, 1.6, 54000, 1200),
  ($str$Vertical Injection Molder | 800kN | 3K | 49g | 4 Station | 1200mm$str$, 800, 49, 3.7, 300, 600, 0, 0, 3, 4, false, $str$Vertical$str$, 1.6, 80000, 1200)
) AS v(machine_name, clamp_kn, shot_g, dry_cycle_s, min_mold_mm, max_mold_mm, tie_bar_h, tie_bar_v, units, stations, rotating_stack, orientation, index_s, injection_rate, table_mm)
WHERE m.machine_class = 'assembly_plastic_molding_multi_shot_molding' AND m.machine_name = v.machine_name;

-- 4. The loaders: the keys the insert loading code reads (sand-machines machineText 'loading', machineValue 'max_payload').
UPDATE mhr_records SET
  specs = specs || jsonb_strip_nulls(jsonb_build_object('loading', specs->>'loading_type', 'max_payload', (specs->>'max_payload_kg')::numeric)),
  updated_at = now()
WHERE machine_class = 'assembly_plastic_molding_pick_and_place' AND specs ? 'loading_type';

DO $apm_check$
DECLARE bare integer;
BEGIN
  SELECT count(*) INTO bare FROM mhr_records WHERE machine_class = 'assembly_plastic_molding_multi_shot_molding' AND (max_tonnage IS NULL OR shot_capacity_grams IS NULL OR NOT specs ? 'injection_units');
  IF bare > 0 THEN RAISE EXCEPTION 'Assembly Plastic Molding: % multi-shot press row(s) still have no press attributes', bare; END IF;
END $apm_check$;

NOTIFY pgrst, 'reload schema';
